#!/usr/bin/env bash
# autopilot-wrapper: generated by autopilot-setup; set-docs regenerates it.
# codex_command for ralphex: routes Codex runs (the external review, or the executor when
# executor = codex) through agrouter. ralphex execs codex_command as one executable (no word
# splitting), calls it as `<codex_command> exec <codex options>` and pipes the prompt on stdin.
# agrouter emits codex's own `exec`, so the leading one is dropped here; every other option
# reaches codex unchanged after "--".
# --doc files feed agrouter's project-complexity stage only; codex never sees them.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# project docs, relative to the repository root
docs=(
__DOCS__
)
# every *.md in these directories is added too, so new docs are picked up automatically
doc_dirs=(
__DOC_DIRS__
)

args=()
for doc in ${docs[@]+"${docs[@]}"}; do
  args+=(--doc="$root/$doc")
done
for dir in ${doc_dirs[@]+"${doc_dirs[@]}"}; do
  for doc in "$root/$dir"/*.md; do
    if [[ -f "$doc" ]]; then
      args+=(--doc="$doc")
    fi
  done
done

if [[ "${1:-}" == exec ]]; then
  shift
fi

exec agrouter exec codex ${args[@]+"${args[@]}"} -- "$@"
